export const localCastQueueSource = "(() => {\nfunction duration(seconds) { return Math.floor(seconds / 60) + ':' + String(Math.floor(seconds % 60)).padStart(2, '0'); }\nfunction createLocalCastQueueView(list, status, count, labels, select, fallbackCover, resolveCover) {\n    let pending = [];\n    let loading = 0;\n    const sources = new WeakMap();\n    function pump() {\n        while (loading < 3 && pending.length > 0) {\n            const item = pending.shift();\n            loading++;\n            void resolveCover(item.url).then(url => {\n                if (item.image.isConnected)\n                    item.image.src = url || fallbackCover;\n            }).catch(() => { }).finally(() => { loading--; pump(); });\n        }\n    }\n    const observer = new IntersectionObserver(entries => {\n        entries.forEach(entry => {\n            if (!entry.isIntersecting)\n                return;\n            const url = sources.get(entry.target);\n            observer.unobserve(entry.target);\n            pending.push({ image: entry.target, url });\n        });\n        pump();\n    }, { root: list, rootMargin: '120px' });\n    function renderRow(row, current, version) {\n        const button = document.createElement('button');\n        button.className = 'queue-item';\n        if (row.index === current)\n            button.classList.add('current');\n        const cover = document.createElement('img');\n        cover.className = 'queue-item-cover';\n        cover.alt = '';\n        cover.loading = 'lazy';\n        cover.decoding = 'async';\n        cover.onerror = () => { cover.onerror = null; cover.src = fallbackCover; };\n        cover.src = fallbackCover;\n        if (row.coverUrl) {\n            sources.set(cover, row.coverUrl);\n            observer.observe(cover);\n        }\n        const text = document.createElement('span');\n        text.className = 'queue-item-text';\n        const title = document.createElement('span');\n        title.className = 'queue-item-title';\n        title.textContent = row.title;\n        const detail = document.createElement('span');\n        detail.className = 'queue-item-detail';\n        detail.textContent = row.artist + ' · ' + duration(row.duration);\n        if (row.index === current)\n            detail.textContent = labels.current + ' · ' + detail.textContent;\n        text.append(title, detail);\n        button.append(cover, text);\n        button.addEventListener('click', () => select(row, version));\n        return button;\n    }\n    function update(state) {\n        status.textContent = state.shuffleOnQueueEnd ? labels.enabled : labels.disabled;\n        if (!state.queue)\n            return;\n        observer.disconnect();\n        pending = [];\n        const queue = state.queue;\n        list.replaceChildren(...queue.items.map(row => renderRow(row, queue.currentIndex, queue.version)));\n        count.textContent = queue.remaining > 50 ? labels.more.replace('{count}', String(queue.remaining)) : '';\n        if (queue.items.length === 0)\n            count.textContent = labels.empty;\n    }\n    return { update };\n}\nreturn createLocalCastQueueView;\n})()";
export const localCastLyricsSource = "function createLocalCastLyricsView(scroller, presence, parse, noLyrics) {\n    let token = null;\n    let text = '';\n    let lyrics = [];\n    let active = -1;\n    function reset() {\n        active = -1;\n        scroller.style.transition = 'none';\n        scroller.style.transform = 'translateY(0px)';\n        scroller.parentElement.scrollTop = 0;\n        // Flush the layout before restoring transitions so the reset stays immediate.\n        Reflect.get(scroller, 'offsetHeight');\n        scroller.style.transition = '';\n    }\n    function select(nextToken, nextText) {\n        if (token === nextToken && text === nextText)\n            return;\n        token = nextToken;\n        text = nextText;\n        reset();\n        lyrics = parse(text);\n        scroller.replaceChildren(...lyrics.map(line => {\n            const element = document.createElement('div');\n            element.className = 'lyric-line';\n            element.textContent = line.text;\n            return element;\n        }));\n        if (lyrics.length === 0) {\n            const empty = document.createElement('div');\n            empty.className = 'lyrics-empty';\n            empty.textContent = noLyrics;\n            scroller.append(empty);\n        }\n        presence(lyrics.length > 0);\n    }\n    function sync(position) {\n        let index = -1;\n        lyrics.forEach((line, candidate) => {\n            if (position >= line.time)\n                index = candidate;\n        });\n        if (index === active)\n            return;\n        active = index;\n        Array.from(scroller.children).forEach((line, candidate) => line.classList.toggle('active', candidate === active));\n        if (index < 0) {\n            reset();\n            return;\n        }\n        const line = scroller.children[index];\n        const offset = -(line.offsetTop - scroller.parentElement.clientHeight / 2 + line.clientHeight / 2);\n        scroller.style.transform = 'translateY(' + offset + 'px)';\n    }\n    return { select, sync };\n}";
export const localCastThemeSource = "function createLocalCastThemeView(style, initialTheme) {\n    let theme = initialTheme;\n    return {\n        getTheme: () => theme,\n        sync(state) {\n            if (!state.theme || state.theme === theme || typeof state.themeCss !== 'string')\n                return;\n            style.textContent = state.themeCss;\n            theme = state.theme;\n        },\n    };\n}";
